<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:9px;margin:28px}h1{color:#172554;margin:0 0 5px;font-size:25px}.hero{background:#172554;color:white;padding:20px;border-radius:10px;margin-bottom:16px}table{width:100%;border-collapse:collapse}th{background:#312e81;color:white;text-align:left;padding:8px}td{padding:8px;border-bottom:1px solid #e2e8f0;vertical-align:top}.num{text-align:right}.green{color:#059669;font-weight:bold}</style></head><body><div class="hero"><h1 style="color:white">Customers</h1><div>Amanelle Shop &middot; Generated {{ now()->format('M d, Y H:i') }}</div></div><table><thead><tr><th>Customer</th><th>Email</th><th>Phone</th><th>City</th><th>Address</th><th class="num">Orders</th><th class="num">Total spent</th><th>Last order</th></tr></thead><tbody>@foreach($customers as $customer)<tr><td>{{ $customer['name'] }}</td><td>{{ $customer['email'] ?: '-' }}</td><td>{{ $customer['phone'] }}</td><td>{{ $customer['city'] }}</td><td>{{ $customer['address'] }}</td><td class="num">{{ $customer['orders'] }}</td><td class="num green">${{ number_format($customer['total'],2) }}</td><td>{{ $customer['last_order']?->format('M d, Y') }}</td></tr>@endforeach</tbody></table></body></html>
